insert into public.products (id,name,subtitle,family,notes,price,size,image,mood,description,status,sort_order) values ('jardim','Jardim de Lisboa','Uma pausa em tons de verde','Frescas','Chá verde · figueira · cedro',26,'180 g','assets/matcha.webp','Serenidade','A luz atravessa a janela. O dia abranda. Uma composição imaginada entre a frescura do chá verde e o lado acolhedor da madeira, para dar espaço aos pequenos intervalos.','published',0) on conflict (id) do nothing;
insert into public.products (id,name,subtitle,family,notes,price,size,image,mood,description,status,sort_order) values ('marrakech','Sol de Marrakech','O calor de um lugar que fica','Amadeiradas','Flor de laranjeira · âmbar · sândalo',29,'180 g','assets/amber.webp','Aconchego','Há viagens que continuam em nós muito depois do regresso. Notas quentes e luminosas desenham uma memória de pátios tranquilos, terra quente e fins de tarde demorados.','published',1) on conflict (id) do nothing;
insert into public.products (id,name,subtitle,family,notes,price,size,image,mood,description,status,sort_order) values ('raiz','Raiz','Um encontro com o que é nosso','Florais','Jasmim · coco · madeiras suaves',28,'180 g','assets/raiz.webp','Pertença','Um regresso imaginado às raízes brasileiras: familiar, luminoso e cheio de afeto. Uma vela pensada para os espaços onde queremos simplesmente ser.','published',2) on conflict (id) do nothing;
insert into public.products (id,name,subtitle,family,notes,price,size,image,mood,description,status,sort_order) values ('mare','Maré Serena','O espaço entre dois pensamentos','Frescas','Sal marinho · bergamota · almíscar',27,'180 g','assets/mare.webp','Leveza','Inspirada no encontro entre a luz portuguesa e a vastidão do Atlântico. Um aroma imaginado para abrir as janelas por dentro e deixar o tempo encontrar o seu ritmo.','published',3) on conflict (id) do nothing;
insert into public.site_content (id,data) values ('site','{"announcement":"O primeiro capítulo da Avoya · Pré-lançamento","heroEyebrow":"Feito com tempo. Sentido com calma.","heroTitle":"Pequenos rituais.\nNovos sentidos.","heroDescription":"Velas que guardam lugares, despertam memórias e tornam o quotidiano um pouco mais nosso.","heroImage":"assets/hero.webp","heroImageAlt":"Velas Avoya em tons de matcha e marfim, à luz natural","originTitle":"De tantos lugares,\num caminho\nfeito à mão.","originP1":"Do Brasil trouxe as raízes. Das viagens pela Europa e por África, um olhar atento às cores, aos aromas e às pequenas coisas que ficam.","originP2":"Em Portugal, encontrou espaço para escutar uma nova vontade: criar com as mãos. A Avoya nasceu desse encontro entre descoberta, coragem e cuidado.","originImage":"assets/atelier.webp","storyTitle":"Criar também é\numa forma de\nnos encontrarmos.","storyName":"Simone Martins","storyMeta":"Brasil, 1991 · Portugal, desde 2023","storyIntro":"A Avoya começa muito antes da primeira vela. Começa numa mulher que aprendeu a olhar para os recomeços como um lugar de possibilidade.","storyImage":"assets/atelier.webp","storyImageAlt":"Representação ilustrativa do trabalho artesanal com velas, sem retratar Simone","storyImageCaption":"Uma imagem do universo artesanal.\nO retrato da Simone chega em breve.","storyP1":"Brasileira, nascida em 1991, Simone Martins chegou a Portugal em 2023. Com ela vieram as raízes, as memórias e uma maneira calorosa de sentir o mundo. Vieram também perguntas, vontades e a curiosidade de descobrir quem poderia ser neste novo lugar.","storyP2":"As viagens pela Europa e por África ampliaram esse olhar. A luz de uma rua, a textura de uma parede, um aroma que atravessa um mercado: pequenos encontros tornaram-se matéria de inspiração. Mais do que guardar destinos, Simone começou a guardar sensações.","storyP3":"Entre a descoberta pessoal e a escuta interior, surgiu a coragem de dar forma a uma vontade: dedicar tempo ao trabalho das mãos. No artesanato de velas, encontrou um ritmo mais atento e uma linguagem para aquilo que nem sempre se explica em palavras.","storyP4":"A Avoya Studio nasce desse percurso. Um estúdio em Portugal, com alma brasileira e o mundo como inspiração. Um lugar para criar velas especiais, pensadas com cuidado para acompanhar os momentos de quem as recebe.","storyClosing":"Porque há coisas que criamos para a casa.\nE outras que acabam por nos fazer sentir em casa."}'::jsonb) on conflict (id) do nothing;
